package io.github.hoangtnedu.java;
import javax.swing.*;import java.awt.*;import java.nio.file.*;
public class App {
 private static SwingWorker<?,?> current;
 public static JFrame window(){JFrame f=new JFrame("HoangTN - Lab 4 SwingWorker");JComboBox<String> task=new JComboBox<>(new String[]{"Dem nguoc","Tien trinh tai","Tong nguyen to","Fibonacci","Dem dong file"});JTextField value=new JTextField("5",30);JTextArea result=new JTextArea();JProgressBar bar=new JProgressBar(0,100);JButton run=new JButton("Chay"),cancel=new JButton("Huy");
 run.addActionListener(e->{run.setEnabled(false);int choice=task.getSelectedIndex();current=new SwingWorker<String,Integer>(){protected String doInBackground()throws Exception{String x=value.getText();if(choice==2)return Long.toString(Jobs.primeSum(Integer.parseInt(x)));if(choice==3)return Jobs.fib(Integer.parseInt(x)).toString();if(choice==4)return Long.toString(Jobs.lines(Path.of(x)));int n=choice==0?Integer.parseInt(x):100;if(n<0||n>3600)throw new IllegalArgumentException("0..3600");for(int i=0;i<=n;i++){if(isCancelled())return "Da huy";publish(choice==0?n-i:i);setProgress(n==0?100:i*100/n);Thread.sleep(choice==0?1000:20);}return "Hoan thanh";}protected void process(java.util.List<Integer> ticks){result.setText(ticks.get(ticks.size()-1).toString());}protected void done(){try{result.setText(get());}catch(Exception ex){result.setText(isCancelled()?"Da huy":"Loi: "+ex.getMessage());}finally{run.setEnabled(true);}}};current.addPropertyChangeListener(p->{if("progress".equals(p.getPropertyName()))bar.setValue((Integer)p.getNewValue());});current.execute();});cancel.addActionListener(e->{if(current!=null)current.cancel(true);});JPanel top=new JPanel();top.add(task);top.add(value);top.add(run);top.add(cancel);f.add(top,BorderLayout.NORTH);f.add(new JScrollPane(result));f.add(bar,BorderLayout.SOUTH);f.setSize(850,400);f.setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);return f;}
 public static void main(String[] args){SwingUtilities.invokeLater(()->window().setVisible(true));}
}